import { request } from '../../utils/request'

// AI聊天对话
export const sendAIMessage = (message: string, sessionId?: string) => {
  return request({
    url: '/api/user/ai/chat',
    method: 'POST',
    data: sessionId ? { message, sessionId } : { message },
    requireAuth: true
  });
}

// 语音识别
export const voiceRecognition = (audioFile: File) => {
  const formData = new FormData();
  formData.append('audio', audioFile);
  
  return request({
    url: '/api/public/ai/voice',
    method: 'POST',
    data: formData,
    requireAuth: false
  });
}

// 获取AI聊天历史
export const getAIChatHistory = (offset = 0, limit = 20) => {
  return request({
    url: '/api/user/ai/chat/history',
    method: 'GET',
    params: { offset, limit },
    requireAuth: true
  });
}

// 获取指定会话的全部聊天记录
export const getAIChatSessionDetail = (sessionId: string) => {
  return request({
    url: '/api/user/ai/chat/session',
    method: 'GET',
    params: { sessionId },
    requireAuth: true
  });
}
